"""FX forward curve, cross rates, portfolio MTM, PnL attribution and delta."""
import csv
import json
import os

DATA = "/app/data"
OUT = "/app/output"


def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as fh:
        return list(csv.DictReader(fh))


def main():
    os.makedirs(OUT, exist_ok=True)
    with open(os.path.join(DATA, "params.json")) as fh:
        params = json.load(fh)
    tenor_days = params["tenor_days"]
    pips = params["pip_multipliers"]

    # ---- spot: drop stale / crossed quotes (bid >= ask)
    spot = {}
    for r in read_csv("spot_rates.csv"):
        bid, ask = float(r["bid"]), float(r["ask"])
        if bid >= ask:
            continue
        if r["pair"] in spot:
            continue
        spot[r["pair"]] = {"bid": bid, "ask": ask, "mid": (bid + ask) / 2,
                           "base": r["base_ccy"], "quote": r["quote_ccy"]}

    # ---- deposits (percent -> decimal) with per-currency day count basis
    dep = {}
    for r in read_csv("deposit_rates.csv"):
        basis = 360.0 if r["day_count"].strip().upper() == "ACT/360" else 365.0
        dep[r["currency"]] = {"1M": float(r["tenor_1m"]) / 100, "3M": float(r["tenor_3m"]) / 100,
                              "6M": float(r["tenor_6m"]) / 100, "basis": basis}

    def growth(ccy, tenor):
        d = dep[ccy]
        return 1.0 + d[tenor] * tenor_days[tenor] / d["basis"]

    def cip_factor(base, quote, tenor):
        return growth(quote, tenor) / growth(base, tenor)

    # ---- Part 1: outright forwards for direct pairs
    fwd_raw, fwd_out, pts_out = {}, {}, {}
    for pair, q in spot.items():
        fwd_raw[pair], fwd_out[pair], pts_out[pair] = {}, {}, {}
        for tenor in tenor_days:
            f = cip_factor(q["base"], q["quote"], tenor)
            fb, fa = q["bid"] * f, q["ask"] * f
            fm = (fb + fa) / 2
            fwd_raw[pair][tenor] = {"bid": fb, "ask": fa, "mid": fm}
            fwd_out[pair][tenor] = {k: round(v, 6) for k, v in fwd_raw[pair][tenor].items()}
            pm = pips.get(pair, 10000)
            pts_out[pair][tenor] = {
                "bid": round((fb - q["bid"]) * pm, 2),
                "ask": round((fa - q["ask"]) * pm, 2),
                "mid": round((fm - q["mid"]) * pm, 2),
            }

    # ---- helpers: express any ccy vs USD as XXX/USD quote (bid, ask, mid)
    def vs_usd(ccy, quotes):
        """quotes: pair -> {bid, ask, mid}; returns (bid, ask, mid) of ccy/USD."""
        if ccy == "USD":
            return 1.0, 1.0, 1.0
        if f"{ccy}/USD" in quotes:
            q = quotes[f"{ccy}/USD"]
            return q["bid"], q["ask"], q["mid"]
        q = quotes[f"USD/{ccy}"]
        return 1.0 / q["ask"], 1.0 / q["bid"], 1.0 / q["mid"]

    def cross(pair, quotes):
        b, qc = pair.split("/")
        xb, xa, xm = vs_usd(b, quotes)
        yb, ya, ym = vs_usd(qc, quotes)
        # XXX/YYY bid = XXX/USD bid * USD/YYY bid, with USD/YYY bid = 1/(YYY/USD ask)
        return {"bid": xb / ya, "ask": xa / yb, "mid": xm / ym}

    spot_q = {p: {"bid": v["bid"], "ask": v["ask"], "mid": v["mid"]} for p, v in spot.items()}
    cross_raw, cross_out, fcross_raw, fcross_out, cip_dev = {}, {}, {}, {}, {}
    # CIP deviation (3M, mid): quoted outright vs S * (1 + r_q t_q) / (1 + r_b t_b)
    for pair, q in spot.items():
        f_cip = q["mid"] * cip_factor(q["base"], q["quote"], "3M")
        cip_dev[pair] = (fwd_raw[pair]["3M"]["mid"] - f_cip) / f_cip * 10000.0
    for pair in params["cross_rates_to_compute"]:
        c = cross(pair, spot_q)
        cross_raw[pair] = c
        cross_out[pair] = {k: round(v, 4) for k, v in c.items()}
        fq = {p: fwd_raw[p]["3M"] for p in fwd_raw}
        fc = cross(pair, fq)
        fcross_raw[pair] = fc
        fcross_out[pair] = {"3M": {k: round(v, 4) for k, v in fc.items()}}
        b, qc = pair.split("/")
        f_cip = c["mid"] * cip_factor(b, qc, "3M")
        cip_dev[pair] = (fc["mid"] - f_cip) / f_cip * 10000.0

    # ---- helpers for any pair
    def spot_mid(pair):
        return spot[pair]["mid"] if pair in spot else cross_raw.get(pair, cross(pair, spot_q))["mid"]

    def fwd_mid(pair, tenor):
        if pair in fwd_raw:
            return fwd_raw[pair][tenor]["mid"]
        return cross(pair, {p: fwd_raw[p][tenor] for p in fwd_raw})["mid"]

    def usd_per(ccy):
        return vs_usd(ccy, spot_q)[2]

    hist = {r["pair"]: float(r["mid"]) for r in read_csv("historical_spots.csv")}

    def hist_mid(pair):
        if pair in hist:
            return hist[pair]
        b, qc = pair.split("/")

        def h_usd(c):
            if c == "USD":
                return 1.0
            if f"{c}/USD" in hist:
                return hist[f"{c}/USD"]
            return 1.0 / hist[f"USD/{c}"]
        return h_usd(b) / h_usd(qc)

    mtm, attr = {}, {}
    net = {}
    for t in read_csv("portfolio.csv"):
        pair, tenor = t["pair"], t["tenor"]
        sign = 1.0 if t["direction"].strip().lower().startswith("buy") else -1.0
        n = float(t["notional_base"])
        k = float(t["trade_rate"])
        b, qc = pair.split("/")
        f_now = fwd_mid(pair, tenor)
        s_now = spot_mid(pair)
        s_hist = hist_mid(pair)
        q2usd = usd_per(qc)
        pnl_q = sign * n * (f_now - k)
        pnl_usd = pnl_q * q2usd
        mtm[t["trade_id"]] = {"current_forward_mid": f_now, "pnl_quote_ccy": pnl_q, "pnl_usd": pnl_usd}
        spot_d = sign * n * (s_now - s_hist) * q2usd
        carry = sign * n * (f_now - s_now) * q2usd
        attr[t["trade_id"]] = {"spot_delta_usd": spot_d, "carry_usd": carry,
                               "residual_usd": pnl_usd - spot_d - carry, "total_usd": pnl_usd}
        net[b] = net.get(b, 0.0) + sign * n * usd_per(b)
        net[qc] = net.get(qc, 0.0) - sign * n * k * q2usd

    res = {
        "forward_rates": fwd_out,
        "forward_points": pts_out,
        "cross_rates": cross_out,
        "forward_cross_rates_3M": fcross_out,
        "cip_deviations_bps": cip_dev,
        "portfolio_mtm": mtm,
        "pnl_attribution": attr,
        "net_delta_usd": net,
    }
    with open(os.path.join(OUT, "results.json"), "w") as fh:
        json.dump(res, fh, indent=2)


if __name__ == "__main__":
    main()
